using System;using UnityEngine;using UnityEngine.InputSystem;using TMPro;
namespace CrossTheLine {
public sealed class MatthewCalling:MonoBehaviour {
 public int Stage{get;private set;}public bool IsCinematic=>joy||(Stage==4&&clock<2);public bool LeftTaxOffice{get;private set;}public bool InvitedHome{get;private set;}public Transform Player=>player;public Transform TaxCollector=>matthew;public Vector3 Target=>target;
 JourneyGame game;Transform player,matthew;Transform[] companions=new Transform[5],critics=new Transform[2];Material mat;Sprite square;GameObject environment;Vector3 target;float clock;bool joy,busy,shutdown,oldPixel;UnityEngine.Rendering.Universal.PixelPerfectCamera pixel;
 public void Initialize(JourneyGame g,Transform p,SpriteRenderer b,Material m,Sprite s,int step){JourneyObjectFactory.BeginStage(this,step);game=g;player=p;mat=m;square=s;pixel=g.journeyCamera.GetComponent<UnityEngine.Rendering.Universal.PixelPerfectCamera>();if(pixel){oldPixel=pixel.enabled;pixel.enabled=false;}ConfigureStep(step);}
 Color C(string h){ColorUtility.TryParseHtmlString("#"+h,out var c);return c;}
 Transform Shape(string name,float x,float y,float w,float h,string color,int order=0){var o=JourneyObjectFactory.Create(name);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 1",new Vector3(x,y,0));o.transform.localScale=new Vector3(w,h,1);var r=o.GetOrAddComponent<SpriteRenderer>();r.sprite=square;r.sharedMaterial=mat;r.color=C(color);r.sortingOrder=order;return o.transform;}
 Transform Actor(string name,Sprite sprite,float x,float y){var o=JourneyObjectFactory.Create(name);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 2",new Vector3(x,y,0));var r=JourneyObjectFactory.Create("Sprite").GetOrAddComponent<SpriteRenderer>();r.transform.SetParent(o.transform,false);r.sharedMaterial=mat;r.sortingOrder=45;r.sprite=sprite;float s=1.7f/sprite.bounds.size.y;r.transform.localScale=Vector3.one*s;r.transform.localPosition=new Vector3(-sprite.bounds.center.x*s,-sprite.bounds.min.y*s,0);int i=Array.IndexOf(game.disciples,sprite);if(i>=0)r.gameObject.GetOrAddComponent<DiscipleWalking>().Initialize(i,o.transform);return o.transform;}
 void Label(string text,float x,float y){var o=JourneyObjectFactory.Create(text);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 3",new Vector3(x,y,0));var t=o.GetOrAddComponent<TextMeshPro>();t.font=game.koreanFont;t.text=text;t.fontSize=2.8f;t.color=C("584a39");t.alignment=TextAlignmentOptions.Center;t.GetComponent<RectTransform>().sizeDelta=new Vector2(8,1);t.GetComponent<MeshRenderer>().sortingOrder=70;}
 void House(float x,float y){Shape("마태의 집",x,y,3.2f,2.4f,"d3b890",-4);Shape("집 지붕",x,y+1.2f,3.5f,.25f,"9b7953",-3);Shape("문",x,y-.55f,.85f,1.35f,"6d543c",-2);}
 public void ConfigureStep(int step){JourneyObjectFactory.BeginStage(this,step);Stage=Mathf.Min(step,4);clock=0;busy=false;joy=false;LeftTaxOffice=Stage>=2;InvitedHome=Stage>=3;if(environment)Destroy(environment);environment=JourneyObjectFactory.Create("MatthewSketchEnvironment");environment.transform.SetParent(transform,false);int[] indices={0,1,2,3,4};if(Stage<3){Shape("가버나움 길",0,0,30,18,"d2bd91",-10);Shape("마을 담",0,3,25,1.5f,"b89d74",-7);House(-7,2);House(7,2);Label("가버나움 · 세금 징수소",1,3.5f);Shape("세금 징수 책상",2,-.3f,3.2f,.55f,"8d633f",30);Shape("세금 장부",1.4f,.05f,.8f,.12f,"e9d9b7",31);for(int i=0;i<8;i++)Shape("남겨 둔 세금 동전 "+i,2.1f+i%4*.19f,.03f+i/4*.14f,.10f,.07f,"d3b35a",32);matthew=Actor("마태",game.disciples[6],2,.25f);for(int i=0;i<4;i++)Actor("세금 내는 사람 "+i,game.supportingCast[i%2==0?5:6],5.8f-i*1.05f,-2.0f-i*.19f);player.position=JourneyStageLayout.Point(this,player,"Placement 4",new Vector3(Stage==2?1:Stage==1?1:-5,Stage==1?-2:-3,0));for(int i=0;i<5;i++)companions[i]=Actor(JourneyGame.ActorNames[indices[i]],game.disciples[indices[i]],-8.0f+i*1.25f,-4.65f);target=new Vector3(Stage==2?6:1,-2,0);if(Stage==2){matthew.position=JourneyStageLayout.Point(this,matthew,"Placement 5",new Vector3(-.3f,-2.8f,0));Label("마태의 집 →",6,3.4f);}}
 else {Shape("잔칫집 바닥",0,0,30,18,"d7c29b",-10);Shape("집 안쪽 벽",0,3.5f,24,2.8f,"e7d8b9",-8);Shape("왼쪽 출입문",-8,1,1.6f,3,"866a4a",-6);Shape("긴 잔칫상",.7f,-.3f,12.5f,1.4f,"8f663f",50);Shape("식탁보",.7f,.4f,12.7f,.18f,"ebddbf",51);for(int i=0;i<7;i++){Shape("음식 접시",-4.5f+i*1.75f,.52f,.65f,.1f,"bf9153",52);Shape("잔",-4+i*1.75f,.62f,.17f,.24f,"d6b57b",53);}player.position=JourneyStageLayout.Point(this,player,"Placement 6",new Vector3(.7f,.8f,0));matthew=Actor("잔치를 연 마태",game.disciples[6],-2.9f,.7f);for(int i=0;i<5;i++)companions[i]=Actor(JourneyGame.ActorNames[indices[i]],game.disciples[indices[i]],-4+i*2.3f,i%2==0?-2.7f:.7f);for(int i=0;i<4;i++)Actor("초대받은 세리와 손님 "+i,game.supportingCast[i%2==0?5:2],-5.7f+i*3.7f,-4.65f);critics[0]=Actor("비난하는 제사장",game.supportingCast[6],-8.5f,1.2f);critics[1]=Actor("비난하는 장로",game.supportingCast[6],-8.5f,-.4f);critics[0].gameObject.SetActive(Stage==4);critics[1].gameObject.SetActive(Stage==4);target=new Vector3(.7f,.8f,0);Label("마태의 집 · 함께하는 잔치",0,3.3f);}
 game.journeyCamera.orthographicSize=5.625f;UpdateCamera();game.BaptismCinema(IsCinematic);Hud();}
 void Hud(){string[] labels={"세금을 걷는 마태에게 다가가기","망설이는 마태를 부르기","모든 것을 두고 따르는 마태와 집으로 가기","마태가 연 잔치에 함께하기","비난에 답하며 부르심의 뜻 전하기"};game.MatthewHud(labels[Stage],Stage==2?"D / → · 마태와 함께 집으로 이동":"WASD / 방향키 · 이동    가까이에서 E · 대화");}
 public void Tick(float dt,bool canMove,bool press){if(joy){clock+=dt;matthew.position=JourneyStageLayout.Point(this,matthew,"Placement 7",new Vector3(2-Mathf.Clamp01(clock/2)*2,-.2f+Mathf.Abs(Mathf.Sin(clock*6))*.25f,0));if(clock>=2.5f){joy=false;game.BaptismCinema(false);game.BaptismAdvance();}return;}if(Stage==4&&clock<2){clock+=dt;critics[0].position=Vector3.MoveTowards(critics[0].position,new Vector3(-5.7f,1.2f,0),dt*2);critics[1].position=Vector3.MoveTowards(critics[1].position,new Vector3(-6,-.4f,0),dt*2);if(clock>=2)game.BaptismCinema(false);return;}if(!canMove||busy)return;var k=Keyboard.current;Vector2 v=Vector2.zero;if(k!=null){v.x=(k.dKey.isPressed||k.rightArrowKey.isPressed?1:0)-(k.aKey.isPressed||k.leftArrowKey.isPressed?1:0);v.y=(k.wKey.isPressed||k.upArrowKey.isPressed?1:0)-(k.sKey.isPressed||k.downArrowKey.isPressed?1:0);}var p=player.position+(Vector3)(v.normalized*3.4f*dt);p.x=Mathf.Clamp(p.x,-8,8);p.y=Mathf.Clamp(p.y,Stage<3?-3.5f:-3.2f,Stage<3?-1.6f:1);player.position=p;game.MeetingWalk(v.sqrMagnitude>0,v.x);if(Stage==2){matthew.position=Vector3.MoveTowards(matthew.position,p+new Vector3(-1.35f,.15f,0),dt*3.4f);for(int i=0;i<5;i++)companions[i].position=Vector3.MoveTowards(companions[i].position,p+new Vector3(-2.6f-i*1.05f,.25f,0),dt*3.4f);if(p.x>=5.8f){game.BaptismAdvance();return;}}Hud();if(press)Interact();}
 public void Interact(){if(busy||IsCinematic||Stage==2)return;if(Vector3.Distance(player.position,target)>1.7f)return;busy=true;game.MeetingTalk(()=>{busy=false;if(Stage==1){joy=true;clock=0;game.BaptismCinema(true);}else game.BaptismAdvance();});}
 public void UpdateCamera(){game.journeyCamera.transform.position=JourneyStageLayout.Point(this,game.journeyCamera.transform,"Placement 8",new Vector3(0,0,-10));}
 public void Shutdown(){if(shutdown)return;shutdown=true;if(pixel)pixel.enabled=oldPixel;}
 void OnDestroy(){Shutdown();}
}
}
